repo.donations.py:
"""Donation records."""


class Donation:
    def __init__(self, donor, pounds):
        self.donor = donor
        self.pounds = pounds

    def __repr__(self):
        return "Donation(%r, %r)" % (self.donor, self.pounds)


ROWS = [('noor', 28), ('mia', 36), ('mia', 43), ('noor', 37), ('mia', 46), ('noor', 52), ('noor', 12)]


def load_donations():
    """Yield the stored donations one at a time."""
    for donor, pounds in ROWS:
        yield Donation(donor, pounds)

repo.shares.py:
"""Share of the total pounds per donation."""
from donations import load_donations


def pounds_shares(donations):
    """Return each donation's share of the total pounds, in order."""
    total = sum(x.pounds for x in donations)
    return [x.pounds / total for x in donations]


def stored_shares():
    """Shares for the stored donations."""
    return pounds_shares(load_donations())


def top_share(donations):
    """Return the largest share, or 0.0 when there are no donations."""
    shares = pounds_shares(donations)
    return max(shares) if shares else 0.0


def describe_donation(donation):
    """Return a one-line description of a donation."""
    return "%s: %s" % (donation.donor, donation.pounds)
